const items = $input.all();
const prices = [];
const seen = new Set();

function cleanText(t) {
  return (t || '')
    .replace(/\s+/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .trim();
}

function pushItem(title, value, source, subcategory, unit = 'ud', description = '') {
  if (!title || !Number.isFinite(value) || value <= 0 || value > 50000) return;
  const key = `${title}|${value}|${source}`;
  if (seen.has(key)) return;
  seen.add(key);
  prices.push({
    title: title.substring(0, 160),
    value: Number(value.toFixed(2)),
    unit,
    category: 'material',
    subcategory,
    source,
    description
  });
}

for (const item of items) {
  const html = item.json.data || item.json.body || '';
  const lower = html.toLowerCase();

  const blocks = html.match(/.{0,250}(€|eur).{0,120}/gi) || [];
  for (const block of blocks.slice(0, 80)) {
    const priceMatch = block.match(/(\d{1,4}(?:[.,]\d{2})?)\s*(?:€|eur)/i);
    if (!priceMatch) continue;
    const value = parseFloat(priceMatch[1].replace(',', '.'));
    const titleMatch =
      block.match(/(?:title|alt|data-name|aria-label|product-name|nombre)[="':>\s]*([^"<>|]{8,140})/i) ||
      block.match(/>([^<>]{8,120})</);
    const rawTitle = titleMatch ? cleanText(titleMatch[1]) : '';
    let source = 'retail-web';
    let subcategory = 'General';
    if (lower.includes('leroymerlin')) source = 'leroy-merlin';
    if (lower.includes('obramat')) source = 'obramat';
    if (/ducha|mampara|lavabo|grifo|inodoro/i.test(rawTitle + ' ' + block)) subcategory = 'Fontaneria';
    else if (/cement|mortero|yeso|escayola|ladrillo|bloque|aislamiento/i.test(rawTitle + ' ' + block)) subcategory = 'Albanileria';

    if (rawTitle && rawTitle.length >= 8) {
      pushItem(rawTitle, value, source, subcategory, 'ud', 'Precio capturado automáticamente desde web retail');
    }
  }
}

if (prices.length === 0) {
  const fechaHoy = new Date().toLocaleDateString('es-ES');
  const fallback = [
    ['Plato de ducha resina 70x120 antideslizante', 189.00, 'Fontaneria'],
    ['Plato de ducha resina 80x120 antideslizante', 199.00, 'Fontaneria'],
    ['Mampara frontal 120 cm corredera', 245.00, 'Fontaneria'],
    ['Mampara fija 80 cm cristal templado', 189.00, 'Fontaneria'],
    ['Saco cemento gris 25 kg CEM II', 4.85, 'Albanileria'],
    ['Saco mortero cola C1 25 kg', 5.90, 'Albanileria'],
    ['Saco mortero cola C2TE 25 kg', 12.50, 'Albanileria'],
    ['Azulejo porcelánico 60x60 rectificado', 19.90, 'Albanileria'],
    ['Azulejo cerámico 30x60 brillo', 13.50, 'Albanileria'],
    ['Grifo termostático ducha visto', 89.00, 'Fontaneria'],
    ['Inodoro compacto adosado a pared', 149.00, 'Fontaneria'],
    ['Mueble lavabo 80 cm + espejo LED', 349.00, 'Fontaneria']
  ];
  for (const [title, value, subcategory] of fallback) {
    pushItem(title, value, 'referencia-mercado-' + fechaHoy, subcategory, title.includes('Azulejo') ? 'm2' : 'ud', 'Precio de referencia de mercado español');
  }
}

return [{ json: { sector: 'construccion', prices } }];

const html = $input.first().json.data || $input.first().json.body || '';
const updates = [];
const seen = new Set();

function cleanText(t) {
  return (t || '').replace(/\s+/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').trim();
}

const cardRegex = /<a[^>]+href="([^"]*generador-de-precios[^"]*)"[^>]*>[\s\S]{0,800}?<h[23][^>]*>([\s\S]{1,220}?)<\/h[23]>[\s\S]{0,500}?(?:Publicado el\s*([^<]+))?/gi;
let m;
while ((m = cardRegex.exec(html)) !== null && updates.length < 8) {
  const url = m[1].startsWith('http') ? m[1] : ('https://info.cype.com' + m[1]);
  const title = cleanText(m[2]).replace(/<[^>]+>/g, '');
  const published = cleanText(m[3] || '');
  if (!title || seen.has(title)) continue;
  seen.add(title);
  updates.push({
    title: title.substring(0, 180),
    description: (published ? `Publicado: ${published}. ` : '') + 'Novedad detectada en CYPE Generador de precios.',
    source: 'cype-generador-precios',
    metadata: { url, fecha: new Date().toISOString() }
  });
}

if (updates.length === 0) {
  updates.push({
    title: 'Revisar novedades del Generador de precios de CYPE',
    description: 'No se pudieron parsear tarjetas de novedad. Visita manualmente: https://info.cype.com/es/programa_relacionado/generador-de-precios/',
    source: 'cype-generador-precios',
    metadata: { url: 'https://info.cype.com/es/programa_relacionado/generador-de-precios/', fecha: new Date().toISOString() }
  });
}

return [{ json: { sector: 'construccion', cype_updates: updates } }];

const xml = $input.first().json.data || $input.first().json.body || '';
const regulations = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
const titleRegex = /<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>|<title>([\s\S]*?)<\/title>/i;
const descRegex = /<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>|<description>([\s\S]*?)<\/description>/i;
const linkRegex = /<link>([^<]+)<\/link>/i;
const keywords = ['construcci','edific','vivienda','urbanis','reforma','instalaci','electri','fontaner','climat','residuo','seguridad','laboral','prevencion','iva','fiscal','autonomo','empresa','comercio','sanitar','hostel','alimenta'];

let m;
while ((m = itemRegex.exec(xml)) !== null) {
  const item = m[1];
  const title = ((item.match(titleRegex) || [])[1] || (item.match(titleRegex) || [])[2] || '').trim();
  const desc = ((item.match(descRegex) || [])[1] || (item.match(descRegex) || [])[2] || '').trim();
  const link = ((item.match(linkRegex) || [])[1] || '').trim();
  const txt = (title + ' ' + desc).toLowerCase();
  if (title && keywords.some(k => txt.includes(k))) {
    regulations.push({
      title: title.substring(0, 200),
      description: desc.substring(0, 500),
      source: 'boe-rss',
      metadata: { url: link, fecha: new Date().toISOString() }
    });
  }
}
if (regulations.length === 0) {
  regulations.push({
    title: 'Sin nuevas normativas relevantes hoy',
    description: 'No se han detectado publicaciones del BOE relevantes para construcción o reforma en esta comprobación.',
    source: 'boe-rss'
  });
}
return [{ json: { sector: 'construccion', regulations } }];

const xml = $input.first().json.data || $input.first().json.body || '';
const news = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
const titleRegex = /<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>|<title>([\s\S]*?)<\/title>/i;
const linkRegex = /<link>([^<]+)<\/link>/i;
const pubDateRegex = /<pubDate>([^<]+)<\/pubDate>/i;
let m, count = 0;
while ((m = itemRegex.exec(xml)) !== null && count < 6) {
  const item = m[1];
  const title = ((item.match(titleRegex) || [])[1] || (item.match(titleRegex) || [])[2] || '').trim();
  const link = ((item.match(linkRegex) || [])[1] || '').trim();
  const pubDate = ((item.match(pubDateRegex) || [])[1] || '').trim();
  if (title) {
    news.push({
      title: title.substring(0, 200),
      content: `Fecha: ${pubDate || 'hoy'}${link ? ' | URL: ' + link : ''}`,
      source: 'google-news-rss',
      metadata: { url: link, fecha: new Date().toISOString() }
    });
    count++;
  }
}
if (news.length === 0) {
  news.push({
    title: 'Sin noticias relevantes del sector hoy',
    content: 'No se han detectado noticias nuevas en esta comprobación.',
    source: 'google-news-rss'
  });
}
return [{ json: { sector: 'construccion', news } }];

// Procesar datos JSON del INE (API pública)
const ineData = $input.first().json;
const signals = [];
const fecha = new Date().toISOString();

// La API devuelve un array de series con datos
if (Array.isArray(ineData)) {
  for (const serie of ineData.slice(0, 25)) {
    const nombre = (serie.Nombre || serie.nombre || '').replace(/<[^>]*>/g, '').trim();
    const datos = serie.Data || serie.data || [];

    if (nombre && datos.length > 0) {
      const ultimoValor = datos[0].Valor;
      const penultimoValor = datos.length > 1 ? datos[1].Valor : null;
      const variacion = (ultimoValor != null && penultimoValor != null && penultimoValor !== 0)
        ? ((ultimoValor - penultimoValor) / penultimoValor * 100).toFixed(2)
        : '0';
      const periodo = datos[0].Fecha 
        ? new Date(datos[0].Fecha / 1000).toLocaleDateString('es-ES')
        : 'último periodo';

      signals.push({
        name: nombre.substring(0, 150),
        value: ultimoValor,
        previous_value: penultimoValor,
        variation_pct: parseFloat(variacion),
        unit: 'index',
        source: 'INE-API',
        description: `Índice ${nombre} - Periodo: ${periodo} - Variación: ${variacion}%`,
        captured_at: fecha
      });
    }
  }
}

if (signals.length === 0) {
  signals.push({
    name: 'INE API check',
    value: null,
    unit: 'n/a',
    source: 'INE-API',
    description: 'No se pudieron obtener datos de la API del INE. Verificar endpoint.',
    captured_at: fecha
  });
}

return [{ json: { sector: 'construccion', market_signals: signals, source: 'INE-API', total: signals.length } }];

// Extraer precio electricidad de ESIOS/REE
const html = $input.first().json.data || $input.first().json.body || '';
const signals = [];
const fecha = new Date().toISOString();

// Intentar extraer precio medio del PVPC
const precioMatch = html.match(/(?:precio medio|media)[^0-9]{0,80}?(\d{1,4}[.,]\d{1,4})\s*(?:€\/(?:MWh|kWh)|cts)/i)
  || html.match(/(\d{1,3}[.,]\d{2,4})\s*€\/MWh/i)
  || html.match(/pvpc[^0-9]{0,60}?(\d{1,4}[.,]\d{1,4})/i);

if (precioMatch) {
  const valor = parseFloat(precioMatch[1].replace(',', '.'));
  signals.push({
    name: 'electricidad_pvpc_media_hoy',
    value: valor,
    unit: 'EUR/MWh',
    source: 'ESIOS-REE',
    description: 'Precio medio PVPC electricidad España hoy',
    captured_at: fecha
  });
}

// Intentar extraer máximo y mínimo
const maxMatch = html.match(/(?:máxim|max)[^0-9]{0,40}?(\d{1,4}[.,]\d{1,4})\s*(?:€|cts)/i);
const minMatch = html.match(/(?:mínim|min)[^0-9]{0,40}?(\d{1,4}[.,]\d{1,4})\s*(?:€|cts)/i);
if (maxMatch) signals.push({ name: 'electricidad_pvpc_max_hoy', value: parseFloat(maxMatch[1].replace(',', '.')), unit: 'EUR/MWh', source: 'ESIOS-REE', description: 'Precio máximo PVPC hoy', captured_at: fecha });
if (minMatch) signals.push({ name: 'electricidad_pvpc_min_hoy', value: parseFloat(minMatch[1].replace(',', '.')), unit: 'EUR/MWh', source: 'ESIOS-REE', description: 'Precio mínimo PVPC hoy', captured_at: fecha });

if (signals.length === 0) {
  signals.push({
    name: 'electricidad_pvpc_monitor',
    value: null,
    unit: 'EUR/MWh',
    source: 'ESIOS-REE',
    description: 'No se pudo extraer el precio PVPC. ESIOS puede requerir API token. Consulta: https://www.esios.ree.es/es/pvpc',
    captured_at: fecha
  });
}

return [{ json: { sector: 'construccion', market_signals: signals, source: 'ESIOS-REE' } }];

