try {
  let t = $input.first().json.text || '';
  t = t.replace(/```json/g, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(t);
  const aiData = Array.isArray(parsed) ? parsed : (parsed.market_signals || []);
  if (aiData.length === 0) throw new Error("No items");

  const prices = aiData.map(s => ({ title: s.title || s.name, value: s.value, unit: s.unit, category: 'energia', source: s.source, description: s.description || s.summary, metadata: { captured_at: s.captured_at } }));
  return [{ json: { action: 'update_prices', sector: 'construccion', data: { prices } } }];
} catch(e) {
  const fallbackItems = $items("Procesar precio electricidad");
  const fb = fallbackItems && fallbackItems.length > 0 && fallbackItems[0].json ? fallbackItems[0].json.market_signals : ($json.market_signals || []);
  const prices = fb.map(s => ({ title: s.name, value: s.value, unit: s.unit, category: 'energia', source: s.source, description: s.description, metadata: { captured_at: s.captured_at } }));
  return [{ json: { action: 'update_prices', sector: 'construccion', data: { prices } } }];
}

const aiData = $json.news || [];
const fallbackData = $items("Extraer noticias relevantes")[0]?.json?.news || [];
const items = aiData.length > 0 ? aiData : fallbackData;

const news = items.map(n => ({
  title: n.title || 'Sin título',
  content: n.summary || n.sector_impact || n.description || n.content || 'Sin contenido',
  source: n.source || 'google-news',
  metadata: n.metadata || {}
}));

return [{
  json: {
    action: "update_news",
    sector: "construccion",
    data: { news }
  }
}];

const aiData = $json.regulations || [];
const fallbackData = $items("Filtrar normativas relevantes")[0]?.json?.regulations || [];
const items = aiData.length > 0 ? aiData : fallbackData;

const regulations = items.map(n => ({
  title: n.title || 'Sin título',
  description: n.summary || n.recommended_action || n.description || 'Sin descripción',
  source: n.source || 'boe',
  metadata: n.metadata || {}
}));

return [{
  json: {
    action: "update_regulations",
    sector: "construccion",
    data: { regulations }
  }
}];

const aiData = $json.market_signals || [];
const fallbackData = $items("Procesar datos INE")[0]?.json?.market_signals || [];
const items = aiData.length > 0 ? aiData : fallbackData;

const validPrices = items.filter(s => 
  s.value !== null && s.value !== undefined && !isNaN(s.value)
).slice(0, 15).map(s => ({
  title: s.title || s.name || 'Índice INE',
  value: s.value,
  unit: s.unit || 'index',
  category: s.category || 'indice_mercado',
  subcategory: s.subcategory || 'general',
  source: s.source || 'INE',
  description: s.description || s.summary || '',
  metadata: s.metadata || {}
}));

if (validPrices.length === 0) {
  return [{ json: { skip_send: true, reason: "No hay índices INE válidos para enviar a Enlaze" } }];
}

return [{
  json: {
    action: "update_prices",
    sector: "construccion",
    data: { prices: validPrices }
  }
}];
